import java.time.Duration;
import java.time.ZoneId;
import java.time.ZonedDateTime;

public class FlightClockTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static final ZoneId NEW_YORK = ZoneId.of("America/New_York");
    static final ZoneId TOKYO = ZoneId.of("Asia/Tokyo");
    static final ZoneId UTC = ZoneId.of("UTC");

    static Object labelOf(ZonedDateTime moment) {
        try {
            return FlightClock.label(moment);
        } catch (Throwable crash) {
            return "label threw " + crash.getClass().getSimpleName();
        }
    }

    static Object arrivalLabel(ZonedDateTime departure, Duration flight, ZoneId destination) {
        try {
            ZonedDateTime landed = FlightClock.arrival(departure, flight, destination);
            return landed == null ? "<null>" : FlightClock.label(landed);
        } catch (Throwable crash) {
            return "arrival threw " + crash.getClass().getSimpleName();
        }
    }

    static Object offset(ZonedDateTime moment) {
        try {
            return FlightClock.offsetMinutes(moment);
        } catch (Throwable crash) {
            return "offsetMinutes threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        ZonedDateTime summerNoonNy = ZonedDateTime.of(2024, 7, 4, 9, 30, 0, 0, NEW_YORK);
        ZonedDateTime nightBeforeDst = ZonedDateTime.of(2024, 3, 9, 23, 0, 0, 0, NEW_YORK);

        check("label uses the US pattern", "2024-07-04 09:30 EDT", labelOf(summerNoonNy));
        check("label before the clocks change", "2024-03-09 23:00 EST", labelOf(nightBeforeDst));
        check("offset in summer is -240", -240, offset(summerNoonNy));
        check("offset in winter is -300", -300, offset(nightBeforeDst));
        check("a five hour flight over the spring-forward night",
                "2024-03-10 05:00 EDT", arrivalLabel(nightBeforeDst, Duration.ofHours(5), NEW_YORK));
        check("New York to Tokyo lands the next day",
                "2024-07-05 12:30 JST", arrivalLabel(summerNoonNy, Duration.ofHours(14), TOKYO));
        check("the same instant read in UTC",
                "2024-07-04 13:30 UTC", arrivalLabel(summerNoonNy, Duration.ZERO, UTC));
        check("Tokyo is 540 minutes ahead of UTC", 540,
                offset(summerNoonNy.withZoneSameInstant(TOKYO)));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

