/**
 * TASK: Move a departure time across time zones.
 *
 * arrival(departure, flightTime, destination) adds the Duration to the
 * departure and expresses the result in the destination zone. Use
 * withZoneSameInstant so the moment in time is unchanged and only the wall
 * clock is re-read.
 *   2024-03-09T23:00 in America/New_York plus 5 hours, shown in
 *   America/New_York, is 2024-03-10T05:00 -- only four hours later on the
 *   clock, because the clocks jumped forward that night.
 *
 * label(moment) formats a ZonedDateTime as "yyyy-MM-dd HH:mm z" with
 * java.util.Locale.US, e.g. "2024-03-10 05:00 EDT".
 *
 * offsetMinutes(moment) returns the offset from UTC in minutes, e.g. -240 for
 * New York in summer and 540 for Tokyo.
 */
import java.time.Duration;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

public class FlightClock {

    private static final DateTimeFormatter FORMAT =
            DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm z", Locale.US);

    public static ZonedDateTime arrival(ZonedDateTime departure, Duration flightTime, ZoneId destination) {
        return departure.plus(flightTime).withZoneSameInstant(destination);
    }

    public static String label(ZonedDateTime moment) {
        return FORMAT.format(moment);
    }

    public static int offsetMinutes(ZonedDateTime moment) {
        return moment.getOffset().getTotalSeconds() / 60;
    }
}
